  "Gel serum": { ar: "سيروم جل", tr: "Jel serum" },
  "Ghaima crib mobile, Lulu bear, a rolling bead maze and a card in your words.": { ar: "دوّارة المهد Ghaima ودبدوب Lulu ومتاهة خرز دوّارة وبطاقة بكلماتك.", tr: "Ghaima beşik dönencesi, Lulu ayıcık, döner boncuk labirenti ve sizin sözlerinizle bir kart." },
  "Glide it over the lips whenever they feel dry, and before bed.": { ar: "مرّريه على الشفاه كلما شعرتِ بجفافها، وقبل النوم.", tr: "Dudaklarınız kuruduğunda ve yatmadan önce dudaklarınıza sürün." },
  "Glitter upper, rubber sole": { ar: "جزء علوي لامع ونعل مطاطي", tr: "Simli yüzey, kauçuk taban" },
  "Glitter upper, rubber sole.": { ar: "جزء علوي لامع ونعل مطاطي.", tr: "Simli yüzey, kauçuk taban." },
  "Gloss": { ar: "لامعة", tr: "Parlak" },
  "Green tea": { ar: "الشاي الأخضر", tr: "Yeşil çay" },
  "Hair": { ar: "نوع الشعر", tr: "Saç tipi" },
  "Hand wash cold or machine wash on a gentle cycle in a laundry bag; dry flat.": { ar: "يُغسل يدويًا بماء بارد أو في الغسالة على دورة لطيفة داخل كيس غسيل، ويُجفَّف مفرودًا.", tr: "Soğuk suda elde yıkayın veya çamaşır filesinde hassas programda makinede yıkayın; sererek kurutun." },
  "Hand wash cold or on the wool cycle. Dry flat and never hang; no bleach.": { ar: "يُغسل يدويًا بماء بارد أو على برنامج الصوف. يُجفف مسطّحًا ولا يُعلّق أبدًا، ولا يُستخدم المبيّض.", tr: "Soğuk suda elde veya yünlü programında yıkayın. Düz serip kurutun, asla asmayın; çamaşır suyu kullanmayın." },
  "Hand-carved pieces in two woods on a folding wooden board.": { ar: "قطع منحوتة يدويًا من نوعين من الخشب على لوح خشبي قابل للطي.", tr: "Katlanır ahşap tahta üzerinde iki tür ağaçtan el oyması taşlar." },
  "Hand-knitted merino lambs on a beech frame.": { ar: "حملان من صوف الميرينو محبوكة يدويًا على إطار من خشب الزان.", tr: "Kayın çerçeve üzerinde el örgüsü merinos kuzular." },
  "Hand-stitched leather panels around a soft bladder.": { ar: "ألواح جلدية مخيطة يدويًا حول كيس هواء لين.", tr: "Yumuşak bir iç lastik etrafında elle dikilmiş deri paneller." },
  "Handle": { ar: "المقبض", tr: "Sap" },
  "Hangs 60 cm": { ar: "يتدلى بطول 60 cm", tr: "60 cm sarkar" },
