  "Lumora α8 processor": { ar: "معالج Lumora α8", tr: "Lumora α8 işlemci" },
  "Machine wash at 30°C with the zip closed. Hang to dry; do not iron.": { ar: "يُغسل في الغسالة على 30°C والسحّاب مغلق. يُعلّق ليجف، ولا يُكوى.", tr: "Fermuarı kapalı olarak 30°C'de makinede yıkayın. Asarak kurutun; ütülemeyin." },
  "Machine wash at 30°C, inside out, with similar colours. Dry flat in the shade; iron on low.": { ar: "يُغسل في الغسالة على 30°C مقلوبًا مع ألوان مماثلة. يُجفف مسطّحًا في الظل، ويُكوى على حرارة منخفضة.", tr: "30°C'de, ters çevrilmiş olarak, benzer renklerle makinede yıkayın. Gölgede düz serip kurutun; düşük ısıda ütüleyin." },
  "Mahogany and nylon strings": { ar: "خشب الماهوجني وأوتار نايلون", tr: "Maun ve naylon teller" },
  "Massage the shampoo into wet hair and rinse; smooth the conditioner over the lengths, leave it for two minutes and rinse.": { ar: "دلّكي الشامبو في الشعر المبلل واشطفيه، ثم وزّعي البلسم على أطوال الشعر واتركيه دقيقتين واشطفيه.", tr: "Şampuanı ıslak saça masaj yaparak uygulayın ve durulayın; saç kremini boylara yayın, iki dakika bekletin ve durulayın." },
  "Material": { ar: "الخامة", tr: "Malzeme" },
  "Matte": { ar: "مطفية", tr: "Mat" },
  "Matte and satin": { ar: "مطفية وساتان", tr: "Mat ve saten" },
