  "Room for a sweater underneath": { ar: "تتسع لسترة صوفية تحتها", tr: "Altına kazak giymeye uygun" },
  "Rose, peony, white musk": { ar: "الورد، الفاوانيا، المسك الأبيض", tr: "Gül, şakayık, beyaz misk" },
