  "Size": { ar: "المقاس", tr: "Boyut" },
  "Size 3, 58 cm around": { ar: "المقاس 3، محيط 58 cm", tr: "3 numara, 58 cm çevre" },
  "Sizes": { ar: "المقاسات", tr: "Bedenler" },
  "Skin type": { ar: "نوع البشرة", tr: "Cilt tipi" },
  "Smile, sweep the colour over the apples of the cheeks and blend up towards the temples.": { ar: "ابتسمي، ووزّعي اللون على بروز الخدين، ثم ادمجيه نحو الصدغين.", tr: "Gülümseyin, rengi elmacık kemiklerine sürün ve şakaklara doğru yukarı dağıtın." },
  "Smooth resin dice and a cotton bag to keep them.": { ar: "نرد أملس من الراتنج وكيس قطني لحفظه.", tr: "Pürüzsüz reçine zarlar ve saklamak için pamuklu torba." },
  "Snug": { ar: "ضيقة", tr: "Dar" },
  "Snug, footed": { ar: "ضيقة، بقدمين", tr: "Dar, patikli" },
