/** Those of `texts` this list has, in `lang`. */
export function factWordsIn(texts: readonly string[], lang: "ar" | "tr"): Record<string, string> {
  const out: Record<string, string> = {};
  for (const t of texts) {
    const w = FACT_WORDS[t]?.[lang];
    if (w) out[t] = w;
  }
  return out;
}
